class ZipFile::Writer
  # Intercepts writes so byte size and checksum reflect the complete archive,
  # not just data written through Writer#write.
  class DigestingIO
    def initialize(io, writer)
      @io = io
      @writer = writer
    end

    def write(data)
      @writer.__send__(:track_bytes, data)
      @io.write(data)
    end

    def <<(data)
      write(data)
      self
    end

    def method_missing(name, ...)
      @io.public_send(name, ...)
    end

    def respond_to_missing?(name, include_private = false)
      @io.respond_to?(name, include_private) || super
    end
  end

  attr_reader :byte_size

  def initialize(io = nil)
    @entries = []
    @byte_size = 0
    @output_io = wrap(io)
    @streamer = nil
    @digest = Digest::MD5.new
  end

  def stream_to(io)
    @output_io = wrap(io)
  end

  def write(data)
    @output_io.write(data)
  end

  def add_file(path, content = nil, compress: true, &block)
    @entries << path
    write_method = compress ? :write_deflated_file : :write_stored_file

    if block_given?
      streamer.public_send(write_method, path) { |sink| yield sink }
    else
      streamer.public_send(write_method, path) { |sink| sink.write(content.to_s) }
    end
  end
  alias_method :write_file, :add_file
  alias_method :add_entry, :add_file

  def entries
    @entries
  end

  def glob(pattern)
    @entries.select { |e| File.fnmatch(pattern, e) }.sort
  end

  def exists?(path)
    @entries.include?(path)
  end

  def close
    streamer.close
  end

  def checksum
    Base64.strict_encode64(@digest.digest)
  end

  private
    def wrap(io)
      return nil if io.nil?
      return io if io.is_a?(DigestingIO)

      DigestingIO.new(io, self)
    end

    def track_bytes(data)
      @byte_size += data.bytesize
      @digest.update(data)
    end

    def streamer
      @streamer ||= ZipKit::Streamer.new(@output_io)
    end
end
